import json
import re

def parse_script(text):
    nodes = []
    edges = []

    # Extract blocks [ID]\nContent
    # We use a regex that looks for [ID] at the start of a line or start of string
    block_matches = re.findall(r'\[([^\]]+)\]\s*\n(.*?)(?=\n\s*\[|$)', text, re.DOTALL)

    if not block_matches:
        return {"nodes": [], "edges": []}

    node_map = {}
    first_node_id = block_matches[0][0].strip()

    for node_id, content in block_matches:
        node_id = node_id.strip()
        lines = [l.strip() for l in content.strip().split('\n') if l.strip()]

        if not lines:
            # Empty node
            nodes.append({
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "line"
            })
            continue

        is_choice = any(re.match(r'^\d+\.', l) for l in lines)

        if is_choice:
            node_data = {
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "choice"
            }
            for line in lines:
                choice_match = re.match(r'^\d+\.\s*(.*?)\s*->\s*(.*)$', line)
                if choice_match:
                    choice_text = choice_match.group(1).strip()
                    target = choice_match.group(2).strip()
                    edges.append({
                        "from": node_id,
                        "to": target,
                        "text": choice_text
                    })
            nodes.append(node_data)
        else:
            # Line type
            # Expected format: Speaker: Text -> Target
            # Or just Speaker: Text (if it's an end node)
            line_match = re.match(r'^([^:]+):\s*(.*?)\s*->\s*(.*)$', lines[0])
            if line_match:
                speaker = line_match.group(1).strip()
                text_content = line_match.group(2).strip()
                target = line_match.group(3).strip()
                nodes.append({
                    "id": node_id,
                    "text": text_content,
                    "speaker": speaker,
                    "type": "line"
                })
                edges.append({
                    "from": node_id,
                    "to": target,
                    "text": ""
                })
            else:
                line_match_no_target = re.match(r'^([^:]+):\s*(.*)$', lines[0])
                if line_match_no_target:
                    speaker = line_match_no_target.group(1).strip()
                    text_content = line_match_no_target.group(2).strip()
                    nodes.append({
                        "id": node_id,
                        "text": text_content,
                        "speaker": speaker,
                        "type": "line"
                    })
                else:
                    # Fallback
                    nodes.append({
                        "id": node_id,
                        "text": lines[0],
                        "speaker": "",
                        "type": "line"
                    })

    # Reachability check and adding missing nodes
    defined_node_ids = {node["id"] for node in nodes}
    all_target_ids = {edge["to"] for edge in edges}

    for target in all_target_ids:
        if target not in defined_node_ids:
            nodes.append({
                "id": target,
                "text": "",
                "speaker": "",
                "type": "line"
            })
            defined_node_ids.add(target)

    # Filter for reachable nodes from the first node
    reachable = {first_node_id}
    queue = [first_node_id]
    while queue:
        curr = queue.pop(0)
        for edge in edges:
            if edge["from"] == curr and edge["to"] not in reachable:
                reachable.add(edge["to"])
                queue.append(edge["to"])

    nodes = [n for n in nodes if n["id"] in reachable]
    edges = [e for e in edges if e["from"] in reachable and e["to"] in reachable]

    return {"nodes": nodes, "edges": edges}

def generate_dot(graph):
    dot_lines = ["digraph DialogueGraph {"]
    # node [shape=box]; # Optional styling
    for node in graph["nodes"]:
        node_id = node["id"]
        if node["type"] == "line":
            label = f"{node['speaker']}: {node['text']}" if node['speaker'] else node['text']
        else:
            label = f"<{node_id}>"

        if not label:
            label = node_id

        # Escape quotes for DOT
        clean_label = label.replace('"', '\\"')
        dot_lines.append(f'    "{node_id}" [label="{clean_label}"];')

    for edge in graph["edges"]:
        label = edge["text"] if edge["text"] else ""
        clean_label = label.replace('"', '\\"')
        dot_lines.append(f'    "{edge["from"]}" -> "{edge["to"]}" [label="{clean_label}"];')

    dot_lines.append("}")
    return "\n".join(dot_lines)

if __name__ == "__main__":
    with open("/app/script.txt", "r") as f:
        content = f.read()

    graph = parse_script(content)

    with open("/app/dialogue.json", "w") as f:
        json.dump(graph, f, indent=2)

    dot_content = generate_dot(graph)
    with open("/app/dialogue.dot", "w") as f:
        f.write(dot_content)

